import shutil

from ..client_interface import ClientInterface
from ..pyro.pyro_server.rmod_manager import RMODManager


class LocalClient(ClientInterface):
    def __init__(self):
        super().__init__()
        self._rm = RMODManager()

    def setup(self):
        pass

    def _setup_rmod_connection(self, login, password, port):
        return self._rm.setup_rmod_connection(login, password, port)

    def _setup_custom_rmod_connection(self, port, login, password, shell_prompt_regex):
        return self._rm.setup_custom_rmod_connection(port, login, password, shell_prompt_regex)

    def send_command(self, cmd, port, elevated=False, wait_echo=True):
        self._rm.send_command(cmd, port, elevated, wait_echo)

    def execute_command(self, cmd, port, elevated=False, timeout=3, wait_echo=True):
        return self._rm.execute_command(cmd, port, elevated, timeout, wait_echo)

    def take_snapshot(self, port, timeout=180):
        return self._rm.take_snapshot(port, timeout)

    def collect_rmod_output(self, port):
        return self._rm.collect_rmod_output(port)

    def _teardown_rmod_connection(self, port):
        return self._rm.teardown_rmod_connection(port)

    def shutdown(self):
        self.teardown()

    def _download_log(self, local_path, port):
        log_path = self._rm.get_session_log_path(port)
        shutil.copy(log_path, local_path)
        return local_path

    def get_rmod_info(self, port):
        return self._rm.get_rmod_info(port)

    def set_rmod_credentials(self, port, login, password, shell_prompt_regex=None):
        return self._rm.set_rmod_credentials(port, login, password, shell_prompt_regex)
